(()=>{const t=JSON.parse(document.getElementById("raw-copy-data")?.textContent||"{}");if(!Object.keys(t).length)return;const e=document.createElement("div");e.id="raw-copy-toast",document.body.appendChild(e);let n=0;window.copyCode=async o=>{const a=t[o];if("string"!=typeof a||!a.length)return;const c=a.length>0&&await(async t=>{try{return await(navigator.clipboard?.writeText(t)),!0}catch{return!1}})(a);var i;i=c?"Copied":"Copy failed",e.textContent=i,e.style.opacity="1",window.clearTimeout(n),n=window.setTimeout(()=>{e.style.opacity="0"},1200)}})();